-- Every customer with the letters ar in their first name, last name or
-- phone number: three rows, in surname order.
EXEC usp_Customer_Search @SearchText = 'ar';

CREATE OR ALTER PROCEDURE usp_Customer_Add
    @FirstName     VARCHAR(40),
    @LastName      VARCHAR(40),
    @Phone         VARCHAR(15),
    @Email         VARCHAR(100),
    @NewCustomerID INT OUTPUT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    INSERT INTO Customer (FirstName, LastName, Phone, Email)
    VALUES (@FirstName, @LastName, @Phone, @Email);
    SET @NewCustomerID = SCOPE_IDENTITY();
END
GO

-- Add a new customer, print the number the database gave her, then fetch
-- her row back by that number.
DECLARE @NewID INT, @Message VARCHAR(200);

EXEC usp_Customer_Add
     @FirstName = 'Eimear', @LastName = 'Hughes', @Phone = '07700 900 123',
     @Email = 'eimear.hughes@example.com',
     @NewCustomerID = @NewID OUTPUT, @Message = @Message OUTPUT;

IF @Message = ''
BEGIN
    PRINT 'Added. New customer number ' + CAST(@NewID AS VARCHAR) + '.';
END
ELSE
BEGIN
    PRINT @Message;
END

EXEC usp_Customer_GetByID @CustomerID = @NewID;

CREATE OR ALTER PROCEDURE usp_Customer_Update
    @CustomerID INT,
    @FirstName  VARCHAR(40),
    @LastName   VARCHAR(40),
    @Phone      VARCHAR(15),
    @Email      VARCHAR(100),
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    UPDATE Customer
    SET FirstName = @FirstName, LastName = @LastName, Phone = @Phone,
        Email = @Email
    WHERE CustomerID = @CustomerID;
END
GO

-- Change Ben Toner's phone number (customer 12), then fetch his row back.
DECLARE @Message VARCHAR(200);

EXEC usp_Customer_Update
     @CustomerID = 12, @FirstName = 'Ben', @LastName = 'Toner',
     @Phone = '07388 640 999', @Email = 'ben.toner@example.com',
     @Message = @Message OUTPUT;

IF @Message = ''
BEGIN
    PRINT 'Updated customer number 12.';
END
ELSE
BEGIN
    PRINT @Message;
END

EXEC usp_Customer_GetByID @CustomerID = 12;

CREATE OR ALTER PROCEDURE usp_Customer_Delete
    @CustomerID INT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    IF EXISTS (SELECT * FROM Appointment WHERE CustomerID = @CustomerID)
       OR EXISTS (SELECT * FROM Hire     WHERE CustomerID = @CustomerID)
       OR EXISTS (SELECT * FROM PartSale WHERE CustomerID = @CustomerID)
       OR EXISTS (SELECT * FROM Bike     WHERE CustomerID = @CustomerID)
    BEGIN
        SET @Message =
            'This customer has bookings or sales on record, so they cannot ' +
            'be deleted.';
        RETURN;
    END

    DELETE FROM Customer WHERE CustomerID = @CustomerID;
END
GO

-- Try to delete Aoife McCann (customer 1). She has bookings on record, so
-- the stored procedure refuses and hands back its sentence.
DECLARE @Message VARCHAR(200);

EXEC usp_Customer_Delete @CustomerID = 1, @Message = @Message OUTPUT;

IF @Message = ''
BEGIN
    PRINT 'Deleted customer number 1. The rule is broken: she had bookings.';
END
ELSE
BEGIN
    PRINT 'Refused: ' + @Message;
END

-- Add a customer who has no bookings, delete them straight away, then
-- look for them by number: no row comes back.
DECLARE @NewID INT, @Message VARCHAR(200);

EXEC usp_Customer_Add
     @FirstName = 'Niall', @LastName = 'Keenan', @Phone = '07700 900 000',
     @Email = NULL,
     @NewCustomerID = @NewID OUTPUT, @Message = @Message OUTPUT;
PRINT 'Added customer number ' + CAST(@NewID AS VARCHAR) + '.';

EXEC usp_Customer_Delete @CustomerID = @NewID, @Message = @Message OUTPUT;

IF @Message = ''
BEGIN
    PRINT 'Deleted customer number ' + CAST(@NewID AS VARCHAR) + '.';
END
ELSE
BEGIN
    PRINT 'Refused: ' + @Message;
END

EXEC usp_Customer_GetByID @CustomerID = @NewID;

-- Every booking Aoife McCann (customer 1) has, newest first, with the
-- mechanic and the service as names.
EXEC usp_Appointment_GetForCustomer @CustomerID = 1;

CREATE OR ALTER PROCEDURE usp_Staff_Login
    @Username VARCHAR(30),
    @Password VARCHAR(30)
AS
BEGIN
    SELECT StaffID, FirstName + ' ' + LastName AS FullName, Role
    FROM Staff
    WHERE Username = @Username AND Password = @Password AND IsActive = 1;
END
GO

CREATE OR ALTER PROCEDURE usp_Staff_Add
    @FirstName  VARCHAR(40),
    @LastName   VARCHAR(40),
    @Role       VARCHAR(10),
    @Username   VARCHAR(30),
    @Password   VARCHAR(30),
    @NewStaffID INT OUTPUT,
    @Message VARCHAR(200) OUTPUT
AS
BEGIN
    SET @Message = '';
    IF EXISTS (SELECT * FROM Staff WHERE Username = @Username)
    BEGIN
        SET @Message = 'That username is already taken.';
        RETURN;
    END

    INSERT INTO Staff (FirstName, LastName, Role, Username, Password)
    VALUES (@FirstName, @LastName, @Role, @Username, @Password);
    SET @NewStaffID = SCOPE_IDENTITY();
END
GO

-- The mechanics still working (three rows), then everyone (six rows).
EXEC usp_Staff_GetMechanics;
EXEC usp_Staff_GetAll;

